// Doubling Season
// status: ready
// If an effect would create one or more tokens under your control, it creates twice that many of those tokens instead.
// If an effect would put one or more counters on a permanent you control, it puts twice that many of those counters on that permanent instead.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_applies(q: &dyn Query, asker: &Asker, proposal: &Proposal) -> bool { if let Proposal::TokenCreation(t) = proposal { let subject = Target::Player(t.controller); let data = [t.count, u32::MAX]; if t.count > 0 && true && Some(asker.controller) == Some(t.controller) { return true; } }
 false }
#[allow(unused_variables, unused_mut)] fn ability_0_apply(q: &dyn Query, asker: &Asker, proposal: &mut Proposal) { let seen = *proposal; if let Proposal::TokenCreation(seen) = &seen { let t = seen; let subject = Target::Player(t.controller); let data = [t.count, u32::MAX]; if let Proposal::TokenCreation(t) = proposal { t.count = t.count.saturating_mul(2); } } }
#[allow(unused_variables)] fn ability_1_applies(q: &dyn Query, asker: &Asker, proposal: &Proposal) -> bool { if let Proposal::Counters(c) = proposal { let id = c.object; let subject = Target::Object(id); let data = [c.counts.iter().map(|&n| n.max(0) as u32).sum::<u32>(), u32::MAX]; if c.counts.iter().any(|&n| n > 0) && (c.entering || q.is_on_battlefield(id)) && ((q.chars(id).is(CardType::Artifact) || q.chars(id).is(CardType::Battle) || q.chars(id).is(CardType::Creature) || q.chars(id).is(CardType::Enchantment) || q.chars(id).is(CardType::Land) || q.chars(id).is(CardType::Planeswalker)) && Some(asker.controller) == Some(c.controller)) && c.effect { return true; } }
 false }
#[allow(unused_variables, unused_mut)] fn ability_1_apply(q: &dyn Query, asker: &Asker, proposal: &mut Proposal) { let seen = *proposal; if let Proposal::Counters(seen) = &seen { let c = seen; let id = c.object; let subject = Target::Object(id); let data = [c.counts.iter().map(|&n| n.max(0) as u32).sum::<u32>(), u32::MAX]; if let Proposal::Counters(c) = proposal { for i in 0..c.counts.len() { if c.counts[i] > 0 { let data = [c.counts[i] as u32, u32::MAX]; c.counts[i] = ((2i64 * i64::from(data[0]))).min(i16::MAX.into()) as i16; } } } } }

